            last_component_name = 'M'
        elif last_pos_h >= 0:
            last_component_name = 'H'

        # Parse hours
        if 'H' in remaining_time:
            idx = remaining_time.find('H')
            hours_str = remaining_time[:idx]
            allow_decimal = (last_component_name == 'H')
            if not hours_str or not is_valid_number(hours_str, allow_decimal=allow_decimal):
                raise ValueError("Invalid 'H' component")
            hours = parse_number(hours_str)
            has_time_component = True
            remaining_time = remaining_time[idx+1:]

        # Parse minutes
        if 'M' in remaining_time:
            idx = remaining_time.find('M')
            minutes_str = remaining_time[:idx]
            allow_decimal = (last_component_name == 'M')
            if not minutes_str or not is_valid_number(minutes_str, allow_decimal=allow_decimal):
                raise ValueError("Invalid 'M' component")
            minutes = parse_number(minutes_str)
            has_time_component = True
            remaining_time = remaining_time[idx+1:]

        # Parse seconds
        if 'S' in remaining_time:
            idx = remaining_time.find('S')
            seconds_str = remaining_time[:idx]
            allow_decimal = (last_component_name == 'S')
            if not seconds_str or not is_valid_number(seconds_str, allow_decimal=allow_decimal):
                raise ValueError("Invalid 'S' component")
            seconds = parse_number(seconds_str)
            has_time_component = True
            remaining_time = remaining_time[idx+1:]

        # Check that we consumed everything and had at least one component
        if remaining_time:
            raise ValueError("Invalid characters in time part")

        if not has_time_component:
            raise ValueError("'T' must be followed by at least one time component")

    # Check that at least one component is present overall
    if weeks == 0 and days == 0 and hours == 0 and minutes == 0 and seconds == 0:
        # Allow zero values - they are still valid durations
        pass

    total_seconds = weeks * 7 * 86400 + days * 86400 + hours * 3600 + minutes * 60 + seconds
    return total_seconds


def is_valid_number(s: str, allow_decimal: bool = False) -> bool:
    """Check if string is a valid non-negative number"""
    if not s:
        return False

    # Replace comma with period for standardization
    s = s.replace(',', '.')

    # Must have at least one digit
    has_digit = any(c.isdigit() for c in s)
    if not has_digit:
        return False

    # Check format: digits, optionally followed by . and more digits
    parts = s.split('.')
    if len(parts) > 2:
        return False

    if len(parts) == 2:
        if not allow_decimal:
            return False
        # Both parts must have digits or be empty (but not both empty)
        if not parts[0] and not parts[1]:
            return False
        if parts[0] and not all(c.isdigit() for c in parts[0]):
            return False
        if parts[1] and not all(c.isdigit() for c in parts[1]):
            return False
        return parts[0] or parts[1]  # At least one part must have digits

    # Single part, must be all digits
    return all(c.isdigit() for c in parts[0])


def parse_number(s: str) -> float:
    """Parse a number that may have a decimal part using . or ,"""
    s = s.replace(',', '.')
    try:
        return float(s)
    except ValueError:
        raise ValueError(f"Invalid number: {s}")
